-- Additive story timeline. Legacy slots remain readable until they expire.
create table public.story_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id)on delete cascade,kind text not null check(kind in('photo','video','post')),path text unique,post_id uuid references public.feed_posts(id)on delete cascade,photo_index int check(photo_index between 0 and 2),song jsonb check(public.valid_chat_song(song)),duration numeric not null default 10 check(duration>0 and duration<=90),created_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null,check(expires_at=created_at+interval '24 hours'),check((kind='post'and path is null and post_id is not null and photo_index is not null)or(kind in('photo','video')and path is not null and post_id is null)));
alter table public.story_items enable row level security;
create policy story_item_read on public.story_items for select to authenticated using(expires_at>now()and(user_id=auth.uid()or user_id=public.friend_id(auth.uid()))and(kind<>'post'or exists(select from public.feed_posts p where p.id=post_id and auth.uid()in(p.owner_id,p.partner_id))));
grant select on public.story_items to authenticated;grant all on public.story_items to service_role;
create function public.story_active_count(uid uuid)returns bigint language sql stable security definer set search_path=public as $$select(select count(*)from public.story_items where user_id=uid and expires_at>now())+(select count(*)from public.stories where user_id=uid and expires_at>now())+(select count(*)from public.post_stories where user_id=uid and expires_at>now());$$;
revoke all on function public.story_active_count(uuid)from public,anon,authenticated;
create function public.story_item_limit()returns trigger language plpgsql security definer set search_path=public as $$begin perform pg_advisory_xact_lock(hashtextextended(new.user_id::text,18));if public.story_active_count(new.user_id)>=3 then raise exception 'You can have 3 active stories. Delete one or wait for it to expire.';end if;return new;end$$;
revoke all on function public.story_item_limit()from public,anon,authenticated;
create trigger story_item_limit before insert on public.story_items for each row execute function public.story_item_limit();
-- Apply the same per-person lock/cap to legacy clients creating an absent slot.
create trigger legacy_video_story_limit before insert on public.stories for each row execute function public.story_item_limit();
create trigger legacy_post_story_limit before insert on public.post_stories for each row execute function public.story_item_limit();
create table public.story_item_cleanup(path text primary key,queued_at timestamptz not null default now());alter table public.story_item_cleanup enable row level security;revoke all on public.story_item_cleanup from public,anon,authenticated;grant all on public.story_item_cleanup to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('story-items','story-items',false,20971520,array['video/mp4','image/jpeg']);
create function public.story_item_queue()returns trigger language plpgsql security definer set search_path=public as $$begin if old.path is not null then insert into public.story_item_cleanup(path)values(old.path)on conflict do nothing;end if;return old;end$$;
create trigger story_item_removed after delete on public.story_items for each row execute function public.story_item_queue();revoke all on function public.story_item_queue()from public,anon,authenticated;
create function public.story_item_publish(p_user uuid,p_path text,p_kind text,p_duration numeric,p_song jsonb default null)returns uuid language plpgsql security definer set search_path=public as $$declare stamp timestamptz:=clock_timestamp();result uuid;begin
 if p_user is null or public.friend_id(p_user)is null or p_kind not in('photo','video')or p_path!~('^'||p_user::text||'/[0-9a-f-]{36}\.'||case when p_kind='photo'then 'jpg'else 'mp4'end||'$')or not public.valid_chat_song(p_song)or p_duration is null or p_duration<=0 or p_duration>90 then raise exception 'Invalid story';end if;
 if not exists(select from storage.objects where bucket_id='story-items'and name=p_path and(metadata->>'size')::bigint between 1 and 20971520)then raise exception 'Missing upload';end if;
 insert into public.story_items(user_id,kind,path,duration,song,created_at,expires_at)values(p_user,p_kind,p_path,p_duration,p_song,stamp,stamp+interval '24 hours')returning id into result;return result;end$$;
revoke all on function public.story_item_publish(uuid,text,text,numeric,jsonb)from public,anon,authenticated;grant execute on function public.story_item_publish(uuid,text,text,numeric,jsonb)to service_role;
create or replace function public.post_story_publish(p_post uuid,p_index integer)returns void language plpgsql security definer set search_path=public as $$declare uid uuid:=auth.uid();p public.feed_posts;stamp timestamptz:=clock_timestamp();begin
 if uid is null or p_index is null or p_index not between 0 and 2 then raise insufficient_privilege;end if;select * into p from public.feed_posts where id=p_post for share;
 if not found or uid not in(p.owner_id,p.partner_id)or public.friend_id(uid)not in(p.owner_id,p.partner_id)or public.friend_id(uid)is null or p.paths[p_index+1]is null then raise insufficient_privilege;end if;
 insert into public.story_items(user_id,kind,post_id,photo_index,song,created_at,expires_at)values(uid,'post',p.id,p_index,p.song,stamp,stamp+interval '24 hours');end$$;
create function public.story_item_delete(p_id uuid)returns void language plpgsql security definer set search_path=public as $$begin if auth.uid()is null then raise insufficient_privilege;end if;delete from public.story_items where id=p_id and user_id=auth.uid();end$$;
revoke all on function public.story_item_delete(uuid)from public,anon;grant execute on function public.story_item_delete(uuid)to authenticated;
create table public.story_item_views(owner_id uuid not null references public.profiles(id)on delete cascade,viewer_id uuid not null references public.profiles(id)on delete cascade,story_expires_at timestamptz not null,viewed_at timestamptz not null default now(),primary key(owner_id,viewer_id,story_expires_at));
create table public.story_item_reactions(owner_id uuid not null references public.profiles(id)on delete cascade,reactor_id uuid not null references public.profiles(id)on delete cascade,story_expires_at timestamptz not null,emoji text not null check(emoji in('❤️','😍','😂','🔥','👏','😮','🥹','💯')),updated_at timestamptz not null default now(),primary key(owner_id,reactor_id,story_expires_at));
alter table public.story_item_views enable row level security;alter table public.story_item_reactions enable row level security;
create policy item_views_pair on public.story_item_views for select to authenticated using((auth.uid()=owner_id or auth.uid()=viewer_id)and public.friend_id(owner_id)=viewer_id and exists(select from public.story_items where user_id=owner_id and expires_at=story_expires_at and expires_at>now()));
create policy item_reactions_pair on public.story_item_reactions for select to authenticated using((auth.uid()=owner_id or auth.uid()=reactor_id)and public.friend_id(owner_id)=reactor_id and exists(select from public.story_items where user_id=owner_id and expires_at=story_expires_at and expires_at>now()));
grant select on public.story_item_views,public.story_item_reactions to authenticated;grant all on public.story_item_views,public.story_item_reactions to service_role;
create function public.story_item_view(p_owner uuid,p_expires timestamptz)returns void language plpgsql security definer set search_path=public as $$declare uid uuid:=auth.uid();begin if uid is null or uid=p_owner or public.friend_id(uid)is distinct from p_owner then raise insufficient_privilege;end if;perform 1 from public.story_items where user_id=p_owner and expires_at=p_expires and expires_at>now()for share;if not found then raise exception 'Story expired';end if;insert into public.story_item_views(owner_id,viewer_id,story_expires_at)values(p_owner,uid,p_expires)on conflict do nothing;end$$;
create function public.story_item_react(p_owner uuid,p_expires timestamptz,p_emoji text)returns void language plpgsql security definer set search_path=public as $$begin if p_emoji is null or p_emoji not in('❤️','😍','😂','🔥','👏','😮','🥹','💯')then raise exception 'Invalid reaction';end if;perform public.story_item_view(p_owner,p_expires);insert into public.story_item_reactions(owner_id,reactor_id,story_expires_at,emoji)values(p_owner,auth.uid(),p_expires,p_emoji)on conflict(owner_id,reactor_id,story_expires_at)do update set emoji=excluded.emoji,updated_at=now();end$$;
revoke all on function public.story_item_view(uuid,timestamptz),public.story_item_react(uuid,timestamptz,text)from public,anon;grant execute on function public.story_item_view(uuid,timestamptz),public.story_item_react(uuid,timestamptz,text)to authenticated;
create function public.story_item_cleanup_tick()returns void language plpgsql security definer set search_path=public as $$declare secret text;begin delete from public.story_items where expires_at<=now();delete from public.story_item_views where story_expires_at<=now();delete from public.story_item_reactions where story_expires_at<=now();insert into public.story_item_cleanup(path)select o.name from storage.objects o where o.bucket_id='story-items'and o.created_at<now()-interval '1 hour'and not exists(select from public.story_items s where s.path=o.name)on conflict do nothing;select decrypted_secret into secret from vault.decrypted_secrets where name='diary_push_cron'limit 1;if secret is not null then perform net.http_post(url:='https://etkjcywiaiiphsrthxqe.supabase.co/functions/v1/story-items',headers:=jsonb_build_object('Content-Type','application/json','x-diary-cron',secret),body:='{}'::jsonb,timeout_milliseconds:=10000);end if;end$$;
revoke all on function public.story_item_cleanup_tick()from public,anon,authenticated;
select cron.schedule('story-item-cleanup','* * * * *','select public.story_item_cleanup_tick()');
